using System.Text.Json;
using System.Text.RegularExpressions;
using Sharpy.TestInfrastructure.Oracles;
using Xunit;
using ClrType = System.Type;

namespace Sharpy.Core.Tests;

/// <summary>
/// The exception TYPE hierarchy is python's (#2124, P33; COMPARED row 3 of
/// <c>docs/design/python-fidelity-scope.md</c>): one row per public <c>Sharpy.Core</c> type deriving
/// from <see cref="System.Exception"/>, GENERATED by reflection over the Core assembly
/// (<see cref="GeneratedTypes"/>), never a hand-written list, so a new exception type cannot land
/// unmeasured.
/// <para><b>Two oracles, one per kind of row.</b></para>
/// <list type="number">
/// <item><b>.NET bridges</b> — a type whose CLR base chain passes through a <c>System.*</c> type other
/// than <see cref="System.Exception"/> (<c>IOError</c>, <c>OSError</c>, <c>FileNotFoundError</c>,
/// <c>FileExistsError</c>, <c>IsADirectoryError</c>, <c>PermissionError</c> on <c>IOException</c> /
/// <c>FileNotFoundException</c> / <c>UnauthorizedAccessException</c>; <c>ExceptionGroup</c> on
/// <c>AggregateException</c>). The spec bridges these to .NET deliberately (Axiom 1), so the
/// expected base is the spec's: the "Exception Type Hierarchy" table of
/// <c>docs/language_specification/exception_handling.md</c>, read by this test. A bridge type
/// with no spec row fails. Python's chain for them (all → <c>OSError</c> → <c>Exception</c>;
/// <c>ExceptionGroup</c> → <c>BaseExceptionGroup</c>) is not compared; the divergence is the
/// <c>exception-hierarchy-oserror-family-dotnet-bridge</c> row of <c>docs/deviations.yaml</c>.</item>
/// <item><b>Every other type</b> — its Core base chain (bases up to, not including,
/// <see cref="System.Exception"/>) equals python's <c>__mro__</c> after the class itself and
/// <see cref="SpecRemovedPythonLayers"/> are removed. Those removals are spec rulings, not an
/// allowlist: <c>BaseException</c> ("No BaseException": .NET has one root, so <c>SystemExit</c>
/// sits on <c>Exception</c>), <c>Exception</c> and <c>object</c> (the shared root), and
/// <c>DecimalException</c> (the spec's ArithmeticError section omits that layer: <c>InvalidOperation</c>
/// is a sibling directly under <c>ArithmeticError</c>).</item>
/// </list>
/// <para>Both kinds: when the spec table has a row for the type, its base column equals the type's
/// direct CLR base, so the spec table and the code agree on every row it lists.</para>
/// <para><b>Oracle.</b> <c>python3</c>, one batch for every row, through the shared
/// <see cref="PythonInterpreter"/> locator (the precedent of
/// <c>src/Sharpy.Compiler.Tests/Lexer/NumericLiteralTwinTests.cs</c>, #2342): absent → SKIPPED on a
/// developer machine, FAILED under <c>SHARPY_REQUIRE_PYTHON_ORACLE=1</c>. A python namesake is looked
/// up in <c>builtins</c>, then in the stdlib modules whose exception Core hosts at builtin level
/// (<c>argparse.ArgumentError</c>, <c>decimal.InvalidOperation</c>); a Core type with no namesake
/// fails. The builtin exception tree is the same in python 3.9–3.13 (only <c>ExceptionGroup</c> is
/// 3.11+, and it is a bridge row), so any 3.9+ interpreter is a valid oracle.</para>
/// <para>Zero allowlist rows, no Skip: a divergence is fixed in Core or ruled in the spec.</para>
/// </summary>
public class ExceptionHierarchyPythonMroTests
{
    private const int MinPythonMinor = 9;

    /// <summary>Python MRO layers the spec rules out of Sharpy's hierarchy (see the class comment).</summary>
    private static readonly HashSet<string> SpecRemovedPythonLayers =
        new(StringComparer.Ordinal) { "BaseException", "Exception", "object", "DecimalException" };

    private const string OracleScript = """
        import importlib, json, sys
        # builtins first, then the stdlib modules whose exception Sharpy.Core hosts at builtin level.
        MODULES = ["builtins", "argparse", "decimal"]
        for line in sys.stdin:
            name = json.loads(line)
            found = None
            for module in MODULES:
                cls = getattr(importlib.import_module(module), name, None)
                if isinstance(cls, type) and issubclass(cls, BaseException):
                    found = {"name": name, "module": module, "mro": [c.__name__ for c in cls.__mro__]}
                    break
            print(json.dumps(found if found else {"name": name, "module": None, "mro": None}))
        """;

    private static readonly Lazy<Dictionary<string, string>> SpecBases = new(ReadSpecTable);

    private static readonly object OracleLock = new();
    private static Dictionary<string, string[]?>? _pythonMros;

    /// <summary>Every public exception type of the Core assembly: the generated row set.</summary>
    internal static IReadOnlyList<ClrType> GeneratedTypes() =>
        typeof(KeyError).Assembly.GetExportedTypes()
            .Where(t => typeof(Exception).IsAssignableFrom(t) && t != typeof(Exception))
            .OrderBy(t => t.FullName, StringComparer.Ordinal)
            .ToArray();

    /// <summary>The theory's rows, one per generated type, keyed by full name for a readable display.</summary>
    public static IEnumerable<object[]> CoreExceptionTypes() =>
        GeneratedTypes().Select(t => new object[] { t.FullName! });

    /// <summary>
    /// Positive control: the generator yields rows, and the #2124 cell's type is among them, so the
    /// theory cannot pass vacuously over an empty or truncated set.
    /// </summary>
    [Fact]
    public void Generated_set_is_non_empty_and_holds_KeyError()
    {
        var types = GeneratedTypes();
        Assert.NotEmpty(types);
        Assert.Contains(typeof(KeyError), types);
        Assert.Contains(typeof(LookupError), types);
    }

    /// <summary>One row per Core exception type: its base chain against python's MRO or the spec's bridge base.</summary>
    [SkippableTheory]
    [MemberData(nameof(CoreExceptionTypes))]
    public void Base_chain_matches_python_mro_or_spec_bridge(string fullName)
    {
        var type = GeneratedTypes().Single(t => t.FullName == fullName);
        var coreChain = CoreChain(type);
        var directBase = BaseDisplayName(type.BaseType!);

        var specHasRow = SpecBases.Value.TryGetValue(type.Name, out var specBase);
        if (specHasRow)
        {
            Assert.True(specBase == directBase,
                $"{type.Name}: the spec table (exception_handling.md \"Exception Type Hierarchy\") says base " +
                $"`{specBase}`, the Core type derives from `{directBase}`.");
        }

        if (coreChain.Any(IsDotNetBridge))
        {
            Assert.True(specHasRow,
                $"{type.Name} bridges to .NET ({string.Join(" -> ", coreChain.Select(BaseDisplayName))}) but has no row " +
                "in the spec's Exception Type Hierarchy table: a .NET bridge is a spec ruling, so it needs one.");
            return;
        }

        var mros = PythonMros();
        Assert.True(mros.TryGetValue(type.Name, out var mro) && mro is not null,
            $"{type.Name} has no python namesake in builtins/argparse/decimal: a ruling is needed before it can be measured.");
        Assert.Equal(type.Name, mro![0]);

        var expected = mro.Skip(1).Where(n => !SpecRemovedPythonLayers.Contains(n)).ToArray();
        var actual = coreChain.Select(t => t.Name).ToArray();
        Assert.True(expected.SequenceEqual(actual),
            $"{type.Name}: python's MRO is [{string.Join(", ", mro)}], so its bases (spec-removed layers dropped) " +
            $"are [{string.Join(", ", expected)}]; the Core chain is [{string.Join(", ", actual)}].");
    }

    /// <summary>The CLR bases of <paramref name="type"/> up to, not including, <see cref="System.Exception"/>.</summary>
    private static ClrType[] CoreChain(ClrType type)
    {
        var chain = new System.Collections.Generic.List<ClrType>();
        for (var b = type.BaseType; b is not null && b != typeof(Exception); b = b.BaseType)
            chain.Add(b);
        return chain.ToArray();
    }

    private static bool IsDotNetBridge(ClrType t) => t.Assembly != typeof(KeyError).Assembly;

    /// <summary>How the spec table spells a base: <c>System.Exception</c> is <c>Exception</c>, others by simple name.</summary>
    private static string BaseDisplayName(ClrType t) => t == typeof(Exception) ? "Exception" : t.Name;

    private static Dictionary<string, string[]?> PythonMros()
    {
        var python = PythonInterpreter.RequireOrSkip(MinPythonMinor);
        lock (OracleLock)
        {
            if (_pythonMros is not null)
                return _pythonMros;
            var script = Path.Combine(Path.GetTempPath(), $"sharpy-exception-mro-{Guid.NewGuid():N}.py");
            File.WriteAllText(script, OracleScript);
            try
            {
                var names = GeneratedTypes().Select(t => JsonSerializer.Serialize(t.Name)).ToArray();
                var lines = python.RunBatch(script, names);
                var result = new Dictionary<string, string[]?>(StringComparer.Ordinal);
                foreach (var line in lines)
                {
                    using var doc = JsonDocument.Parse(line);
                    var root = doc.RootElement;
                    var mro = root.GetProperty("mro");
                    result[root.GetProperty("name").GetString()!] = mro.ValueKind == JsonValueKind.Null
                        ? null
                        : mro.EnumerateArray().Select(e => e.GetString()!).ToArray();
                }
                Assert.Equal(names.Length, result.Count);
                _pythonMros = result;
                return result;
            }
            finally
            {
                File.Delete(script);
            }
        }
    }

    /// <summary>The spec's "Exception Type Hierarchy" table: Sharpy name → base column.</summary>
    private static Dictionary<string, string> ReadSpecTable()
    {
        var path = PythonInterpreter.FindRepoFile("docs", "language_specification", "exception_handling.md")
            ?? throw new InvalidOperationException("docs/language_specification/exception_handling.md not found above the test binary.");
        var row = new Regex(@"^\|\s*`([A-Za-z_][A-Za-z0-9_]*)`\s*\|\s*`([A-Za-z_][A-Za-z0-9_.]*)`\s*\|", RegexOptions.CultureInvariant);
        var result = new Dictionary<string, string>(StringComparer.Ordinal);
        var inSection = false;
        foreach (var line in File.ReadLines(path))
        {
            if (line.StartsWith("## ", StringComparison.Ordinal) || line.StartsWith("### ", StringComparison.Ordinal))
            {
                if (inSection)
                    break;
                inSection = line.Trim() == "## Exception Type Hierarchy";
                continue;
            }
            if (!inSection)
                continue;
            var m = row.Match(line);
            if (m.Success)
                result[m.Groups[1].Value] = m.Groups[2].Value;
        }
        if (result.Count == 0)
            throw new InvalidOperationException($"No rows parsed from the Exception Type Hierarchy table of {path}.");
        return result;
    }
}
